	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/features/{feature_id}/runs/{run_number}/artifacts", wrapper.ListArtifacts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/features/{feature_id}/runs/{run_number}/artifacts/{artifact_id}", wrapper.GetArtifactContent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/features/{feature_id}/runs/{run_number}/logs/{log_id}", wrapper.GetRunLogContent)
